'use client';

import { CardSection } from '@/components/common/CardSection';
import { SelectField } from '@/components/common/form/SelectField';
import { useCategoryOptions, useLevelOptions } from '@/hooks/useCatalog';
import type { ModuleFormValues } from '@/schemas/module.schema';
import { ModuleImageField } from './ModuleImageField';

// SETTINGS card: level, category and the cover image. The module code (M001) is generated by the API,
// so it isn't a field.
export function ModuleBasicFields() {
   const levelOptions = useLevelOptions();
   const categoryOptions = useCategoryOptions();

   return (
      <CardSection title="Settings">
         <div className="flex flex-col gap-6">
            <div className="grid gap-4 sm:grid-cols-2">
               <SelectField<ModuleFormValues>
                  name="levelId"
                  label="Level"
                  placeholder="Choose module level"
                  options={levelOptions}
               />
               <SelectField<ModuleFormValues>
                  name="categoryId"
                  label="Category"
                  placeholder="Choose category"
                  options={categoryOptions}
               />
            </div>
            <ModuleImageField />
         </div>
      </CardSection>
   );
}
